1	//! Contract module which provides a basic access control mechanism, where
2	//! there is an account (an owner) that can be granted exclusive access to
3	//! specific functions.
4	//!
5	//! The initial owner is set to the address provided by the deployer. This can
6	//! later be changed with [`Ownable::transfer_ownership`].
7	//!
8	//! This module is used through inheritance. It will make available the
9	//! [`Ownable::only_owner`] function, which can be called to restrict operations
10	//! to the owner.
11	use alloc::{vec, vec::Vec};
12	
13	use alloy_primitives::{aliases::B32, Address};
14	use openzeppelin_stylus_proc::interface_id;
15	pub use sol::*;
16	use stylus_sdk::{stylus_core::calls::errors::MethodError, prelude::*, storage::StorageAddress};
17	
18	use crate::utils::introspection::erc165::IErc165;
19	
20	#[cfg_attr(coverage_nightly, coverage(off))]
21	mod sol {
22	    use alloy_sol_macro::sol;
23	
24	    sol! {
25	        /// Emitted when ownership gets transferred between accounts.
26	        ///
27	        /// * `previous_owner` - Address of the previous owner.
28	        /// * `new_owner` - Address of the new owner.
29	        #[derive(Debug)]
30	        #[allow(missing_docs)]
31	        event OwnershipTransferred(address indexed previous_owner, address indexed new_owner);
32	    }
33	
34	    sol! {
35	        /// The caller account is not authorized to perform an operation.
36	        ///
37	        /// * `account` - Account that was found to not be authorized.
38	        #[derive(Debug)]
39	        #[allow(missing_docs)]
40	        error OwnableUnauthorizedAccount(address account);
41	        /// The owner is not a valid owner account. (eg. [`Address::ZERO`])
42	        ///
43	        /// * `owner` - Account that's not allowed to become the owner.
44	        #[derive(Debug)]
45	        #[allow(missing_docs)]
46	        error OwnableInvalidOwner(address owner);
47	    }
48	}
