50	/// An error that occurred in the implementation of an [`Ownable`] contract.
51	#[derive(SolidityError, Debug)]
52	pub enum Error {
53	    /// The caller account is not authorized to perform an operation.
54	    UnauthorizedAccount(OwnableUnauthorizedAccount),
55	    /// The owner is not a valid owner account. (eg. [`Address::ZERO`])
56	    InvalidOwner(OwnableInvalidOwner)}
57	
58	impl MethodError for Error {
59	    fn encode(self) -> alloc::vec::Vec<u8> {
60	        self.into()
61	    }
62	}
