64	/// State of an [`Ownable`] contract.
65	#[storage]
66	pub struct Ownable {
67	    /// The current owner of this contract.
68	    pub(crate) owner: StorageAddress}
69	
70	/// Interface for an [`Ownable`] contract.
71	#[interface_id]
72	#[public]
73	pub trait IOwnable {
74	    /// Returns the address of the current owner.
75	    ///
76	    /// # Arguments
77	    ///
78	    /// * `&self` - Read access to the contract's state.
79	    #[must_use]
80	    fn owner(&self) -> Address;
81	
82	    /// Transfers ownership of the contract to a new account (`new_owner`).
83	    /// Can only be called by the current owner.
84	    ///
85	    /// # Arguments
86	    ///
87	    /// * `&mut self` - Write access to the contract's state.
88	    /// * `new_owner` - The next owner of this contract.
89	    ///
90	    /// # Errors
91	    ///
92	    /// * [`OwnableInvalidOwner`] - If `new_owner` is the [`Address::ZERO`].
93	    ///
94	    /// # Events
95	    ///
96	    /// * [`OwnershipTransferred`].
97	    fn transfer_ownership(&mut self, new_owner: Address)
98	        -> Result<(), Vec<u8>>;
99	
100	    /// Leaves the contract without owner. It will not be possible to call
101	    /// functions that require `only_owner`. Can only be called by the current
102	    /// owner.
103	    ///
104	    /// NOTE: Renouncing ownership will leave the contract without an owner,
105	    /// thereby disabling any functionality that is only available to the owner.
106	    ///
107	    /// # Arguments
108	    ///
109	    /// * `&mut self` - Write access to the contract's state.
110	    ///
111	    /// # Errors
112	    ///
113	    /// * [`Error::UnauthorizedAccount`] - If not called by the owner.
114	    ///
115	    /// # Events
116	    ///
117	    /// * [`OwnershipTransferred`].
118	    fn renounce_ownership(&mut self) -> Result<(), Vec<u8>>;
119	}
120	
121	#[public]
122	#[implements(IOwnable, IErc165)]
123	impl Ownable {
124	    /// Constructor.
125	    ///
126	    /// # Arguments
127	    ///
128	    /// * `&mut self` - Write access to the contract's state.
129	    /// * `initial_owner` - The initial owner of this contract.
130	    ///
131	    /// # Errors
132	    ///
133	    /// * [`Error::InvalidOwner`] - If initial owner is [`Address::ZERO`].
134	    #[constructor]
135	    pub fn constructor(&mut self, initial_owner: Address) -> Result<(), Error> {
136	        if initial_owner.is_zero() {
137	            return Err(Error::InvalidOwner(OwnableInvalidOwner {
138	                owner: Address::ZERO}));
139	        }
140	        self._transfer_ownership(initial_owner);
141	        Ok(())
142	    }
143	}
144	
145	#[public]
146	impl IOwnable for Ownable {
147	    fn owner(&self) -> Address {
148	        self.owner()
149	    }
150	
151	    fn transfer_ownership(
152	        &mut self,
153	        new_owner: Address,
154	    ) -> Result<(), Vec<u8>> {
155	        Ok(self.transfer_ownership(new_owner)?)
156	    }
157	
158	    fn renounce_ownership(&mut self) -> Result<(), Vec<u8>> {
159	        Ok(self.renounce_ownership()?)
160	    }
161	}
