163	impl Ownable {
164	    /// Returns the address of the current owner.
165	    ///
166	    /// # Arguments
167	    ///
168	    /// * `&self` - Read access to the contract's state.
169	    #[must_use]
170	    pub fn owner(&self) -> Address {
171	        self.owner.get()
172	    }
173	
174	    /// Transfers ownership of the contract to a new account (`new_owner`).
175	    /// Can only be called by the current owner.
176	    ///
177	    /// # Arguments
178	    ///
179	    /// * `&mut self` - Write access to the contract's state.
180	    /// * `new_owner` - The next owner of this contract.
181	    ///
182	    /// # Errors
183	    ///
184	    /// * [`Error::InvalidOwner`] - If `new_owner` is the [`Address::ZERO`].
185	    ///
186	    /// # Events
187	    ///
188	    /// * [`OwnershipTransferred`].
189	    pub fn transfer_ownership(
190	        &mut self,
191	        new_owner: Address,
192	    ) -> Result<(), Error> {
193	        self.only_owner()?;
194	
195	        if new_owner.is_zero() {
196	            return Err(Error::InvalidOwner(OwnableInvalidOwner {
197	                owner: Address::ZERO}));
198	        }
199	
200	        self._transfer_ownership(new_owner);
201	
202	        Ok(())
203	    }
204	
205	    /// Leaves the contract without owner. It will not be possible to call
206	    /// functions that require `only_owner`. Can only be called by the current
207	    /// owner.
208	    ///
209	    /// NOTE: Renouncing ownership will leave the contract without an owner,
210	    /// thereby disabling any functionality that is only available to the owner.
211	    ///
212	    /// # Arguments
213	    ///
214	    /// * `&mut self` - Write access to the contract's state.
215	    ///
216	    /// # Errors
217	    ///
218	    /// * [`Error::UnauthorizedAccount`] - If not called by the owner.
219	    ///
220	    /// # Events
221	    ///
222	    /// * [`OwnershipTransferred`].
223	    pub fn renounce_ownership(&mut self) -> Result<(), Error> {
224	        self.only_owner()?;
225	        self._transfer_ownership(Address::ZERO);
226	        Ok(())
227	    }
228	}
229	
230	impl Ownable {
231	    /// Checks if the [`msg::sender`] is set as the owner.
232	    ///
233	    /// # Arguments
234	    ///
235	    /// * `&self` - Read access to the contract's state.
236	    ///
237	    /// # Errors
238	    ///
239	    /// * [`Error::UnauthorizedAccount`] - If called by any account other than
240	    ///   the owner.
241	    pub fn only_owner(&self) -> Result<(), Error> {
242	        let account = self.vm().msg_sender();
243	        if self.owner() != account {
244	            return Err(Error::UnauthorizedAccount(
245	                OwnableUnauthorizedAccount { account },
246	            ));
247	        }
248	
249	        Ok(())
250	    }
251	
252	    /// Transfers ownership of the contract to a new account (`new_owner`).
253	    /// Internal function without access restriction.
254	    ///
255	    /// # Arguments
256	    ///
257	    /// * `&mut self` - Write access to the contract's state.
258	    /// * `new_owner` - Account that is going to be the next owner.
259	    ///
260	    /// # Events
261	    ///
262	    /// * [`OwnershipTransferred`].
263	    pub fn _transfer_ownership(&mut self, new_owner: Address) {
264	        let previous_owner = self.owner.get();
265	        self.owner.set(new_owner);
266	        self.vm().log(OwnershipTransferred { previous_owner, new_owner });
267	    }
268	}
269	
270	#[public]
271	impl IErc165 for Ownable {
272	    fn supports_interface(&self, interface_id: B32) -> bool {
273	        <Self as IOwnable>::interface_id() == interface_id
274	            || <Self as IErc165>::interface_id() == interface_id
275	    }
276	}
