431	        assert_eq!(contract.sender(alice).pending_owner(), bob);
432	
433	        contract
434	            .sender(alice)
435	            .transfer_ownership(dave)
436	            .expect("should overwrite transfer");
437	        assert_eq!(contract.sender(alice).pending_owner(), dave);
438	        assert_eq!(contract.sender(alice).owner(), alice);
439	    }
