1	//! Contract module which provides an access control mechanism, where
2	//! there is an account (an owner) that can be granted exclusive access to
3	//! specific functions.
4	//!
5	//! This extension of the `Ownable` contract includes a two-step mechanism to
6	//! transfer ownership, where the new owner must call
7	//! [`Ownable2Step::accept_ownership`] in order to replace the old one. This can
8	//! help prevent common mistakes, such as transfers of ownership to
9	//! incorrect accounts, or to contracts that are unable to interact with the
10	//! permission system.
11	//!
12	//! The initial owner is set to the address provided by the deployer. This can
13	//! later be changed with [`Ownable2Step::transfer_ownership`] and
14	//! [`Ownable2Step::accept_ownership`].
15	//!
16	//! This module uses [`Ownable`] as a member, and makes all its public functions
17	//! available.
18	
19	use alloc::{vec, vec::Vec};
20	
21	use alloy_primitives::{aliases::B32, Address};
22	use openzeppelin_stylus_proc::interface_id;
23	pub use sol::*;
24	use stylus_sdk::{prelude::*, storage::StorageAddress};
25	
26	use crate::{
27	    access::ownable::{self, Ownable},
28	    utils::introspection::erc165::IErc165};
29	
30	#[cfg_attr(coverage_nightly, coverage(off))]
31	mod sol {
32	    use alloy_sol_macro::sol;
33	
34	    sol! {
35	        /// Emitted when ownership transfer starts.
36	        ///
37	        /// * `previous_owner` - Address of the previous owner.
38	        /// * `new_owner` - Address of the new owner, to which the ownership
39	        ///   will be transferred.
40	        event OwnershipTransferStarted(
41	            address indexed previous_owner,
42	            address indexed new_owner
43	        );
44	
45	    }
46	}
47	
48	/// State of an [`Ownable2Step`] contract.
49	#[storage]
50	pub struct Ownable2Step {
51	    /// [`Ownable`] contract.
52	    // We leave the parent [`Ownable`] contract instance public, so that
53	    // inheritting contract have access to its internal functions.
54	    pub ownable: Ownable,
55	    /// Pending owner of the contract.
56	    pub(crate) pending_owner: StorageAddress}
57	
58	/// Interface for an [`Ownable2Step`] contract.
59	#[interface_id]
60	#[public]
61	pub trait IOwnable2Step {
62	    /// The error type associated to the trait implementation.
63	    type Error: Into<alloc::vec::Vec<u8>>;
64	
65	    /// Returns the address of the current owner.
66	    ///
67	    /// Re-export of [`Ownable::owner`].
68	    ///
69	    /// # Arguments
70	    ///
71	    /// * `&self` - Read access to the contract's state.
72	    fn owner(&self) -> Address;
73	
74	    /// Returns the address of the pending owner.
75	    ///
76	    /// # Arguments
77	    ///
78	    /// * `&self` - Read access to the contract's state.
79	    fn pending_owner(&self) -> Address;
80	
81	    /// Starts the ownership transfer of the contract to a new account.
82	    /// Replaces the pending transfer if there is one. Can only be called by the
83	    /// current owner.
84	    ///
85	    /// Setting `new_owner` to [`Address::ZERO`] is allowed; this can be used
86	    /// to cancel an initiated ownership transfer.
87	    ///
88	    /// # Arguments
89	    ///
90	    /// * `&mut self` - Write access to the contract's state.
91	    /// * `new_owner` - The next owner of this contract.
92	    ///
93	    /// # Errors
94	    ///
95	    /// * [`ownable::Error::UnauthorizedAccount`] - If called by any account
96	    ///   other than the owner.
97	    ///
98	    /// # Events
99	    ///
100	    /// * [`OwnershipTransferStarted`].
101	    fn transfer_ownership(
102	        &mut self,
103	        new_owner: Address,
104	    ) -> Result<(), Self::Error>;
105	
106	    /// Accepts the ownership of the contract.
107	    /// Can only be called by the pending owner.
108	    ///
109	    /// # Arguments
110	    ///
111	    /// * `&mut self` - Write access to the contract's state.
112	    ///
113	    /// # Errors
114	    ///
115	    /// * [`ownable::Error::UnauthorizedAccount`] - If called by any account
116	    ///   other than the pending owner.
117	    ///
118	    /// # Events
119	    ///
120	    /// * [`crate::access::ownable::OwnershipTransferred`].
121	    fn accept_ownership(&mut self) -> Result<(), Self::Error>;
122	
123	    /// Leaves the contract without owner. It will not be possible to call
124	    /// [`Ownable::only_owner`] functions. Can only be called by the current
125	    /// owner.
126	    ///
127	    /// NOTE: Renouncing ownership will leave the contract without an owner,
128	    /// thereby disabling any functionality that is only available to the owner.
129	    ///
130	    /// # Arguments
131	    ///
132	    /// * `&mut self` - Write access to the contract's state.
133	    ///
134	    /// # Errors
135	    ///
136	    /// * [`ownable::Error::UnauthorizedAccount`] - If not called by the owner.
137	    ///
138	    /// # Events
139	    ///
140	    /// * [`crate::access::ownable::OwnershipTransferred`].
141	    fn renounce_ownership(&mut self) -> Result<(), Self::Error>;
142	}
143	
144	#[public]
145	#[implements(IOwnable2Step<Error = ownable::Error>, IErc165)]
146	impl Ownable2Step {
147	    /// See [`Ownable::constructor`].
148	    #[allow(clippy::missing_errors_doc)]
149	    #[constructor]
150	    pub fn constructor(
151	        &mut self,
152	        initial_owner: Address,
153	    ) -> Result<(), ownable::Error> {
154	        self.ownable.constructor(initial_owner)
155	    }
156	}
157	
158	#[public]
159	impl IOwnable2Step for Ownable2Step {
160	    type Error = ownable::Error;
161	
162	    fn owner(&self) -> Address {
163	        self.ownable.owner()
164	    }
165	
166	    fn pending_owner(&self) -> Address {
167	        self.pending_owner.get()
168	    }
169	
170	    fn transfer_ownership(
171	        &mut self,
172	        new_owner: Address,
173	    ) -> Result<(), Self::Error> {
174	        self.ownable.only_owner()?;
175	        self.pending_owner.set(new_owner);
176	
177	        let current_owner = self.owner();
178	        self.vm().log(OwnershipTransferStarted {
179	            previous_owner: current_owner,
180	            new_owner});
181	        Ok(())
182	    }
183	
184	    fn accept_ownership(&mut self) -> Result<(), Self::Error> {
185	        let sender = self.vm().msg_sender();
186	        let pending_owner = self.pending_owner();
187	        if sender != pending_owner {
188	            return Err(ownable::Error::UnauthorizedAccount(
189	                ownable::OwnableUnauthorizedAccount { account: sender },
190	            ));
191	        }
192	        self._transfer_ownership(sender);
193	        Ok(())
194	    }
195	
196	    fn renounce_ownership(&mut self) -> Result<(), Self::Error> {
197	        self.ownable.only_owner()?;
198	        self._transfer_ownership(Address::ZERO);
199	        Ok(())
200	    }
201	}
202	
203	impl Ownable2Step {
204	    /// Transfers ownership of the contract to a new account (`new_owner`) and
205	    /// sets [`Self::pending_owner`] to [`Address::ZERO`] to avoid situations
206	    /// where the transfer has been completed or the current owner renounces,
207	    /// but [`Self::pending_owner`] can still accept ownership.
208	    ///
209	    /// Internal function without access restriction.
210	    ///
211	    /// # Arguments
212	    ///
213	    /// * `&mut self` - Write access to the contract's state.
214	    /// * `new_owner` - Account that's gonna be the next owner.
215	    ///
216	    /// # Events
217	    ///
218	    /// * [`crate::access::ownable::OwnershipTransferred`].
219	    fn _transfer_ownership(&mut self, new_owner: Address) {
220	        self.pending_owner.set(Address::ZERO);
221	        self.ownable._transfer_ownership(new_owner);
222	    }
223	}
224	
225	#[public]
226	impl IErc165 for Ownable2Step {
227	    fn supports_interface(&self, interface_id: B32) -> bool {
228	        <Self as IOwnable2Step>::interface_id() == interface_id
229	            || self.ownable.supports_interface(interface_id)
230	            || <Self as IErc165>::interface_id() == interface_id
231	    }
232	}
