4	//! Call other contracts.
5	//!
6	//! There are two primary ways to make calls to other contracts via the Stylus SDK.
7	//! - [`Call`] with [`sol_interface!`][sol_interface] for richly-typed calls.
8	//! - [`RawCall`] for `unsafe`, bytes-in bytes-out calls.
9	//!
10	//! Additional helpers exist for specific use-cases like [`transfer_eth`].
11	//!
12	//! [sol_interface]: crate::prelude::sol_interface
13	
14	use alloc::vec::Vec;
15	
16	use alloy_primitives::Address;
17	pub(crate) use raw::CachePolicy;
18	pub use raw::RawCall;
19	use stylus_core::{
20	    calls::{errors::Error, MutatingCallContext, StaticCallContext},
21	    Host,
22	};
23	
24	mod raw;
25	
26	/// Provides a convenience method to transfer ETH to a given address.
27	pub mod transfer;
28	
29	/// Static calls the contract at the given address.
30	pub fn static_call<H: Host + ?Sized>(
31	    host: &H,
32	    context: impl StaticCallContext,
33	    to: Address,
34	    data: &[u8],
35	) -> Result<Vec<u8>, Error> {
36	    host.flush_cache(false); // flush storage to persist changes, but don't invalidate the cache
37	    unsafe {
38	        RawCall::new_static(host)
39	            .gas(context.gas())
40	            .call(to, data)
41	            .map_err(Error::Revert)
42	    }
43	}
44	
45	/// Delegate calls the contract at the given address.
46	///
47	/// # Safety
48	///
49	/// A delegate call must trust the other contract to uphold safety requirements.
50	/// Though this function clears any cached values, the other contract may arbitrarily change
51	/// storage, spend ether, and do other things one should never blindly allow other contracts to do.
52	pub unsafe fn delegate_call<H: Host + ?Sized>(
53	    host: &H,
54	    context: impl MutatingCallContext,
55	    to: Address,
56	    data: &[u8],
57	) -> Result<Vec<u8>, Error> {
58	    host.flush_cache(true); // clear storage to persist changes, invalidating the cache
59	
60	    RawCall::new_delegate(host)
61	        .gas(context.gas())
62	        .call(to, data)
63	        .map_err(Error::Revert)
64	}
65	
66	/// Calls the contract at the given address.
67	pub fn call<H: Host + ?Sized>(
68	    host: &H,
69	    context: impl MutatingCallContext,
70	    to: Address,
71	    data: &[u8],
72	) -> Result<Vec<u8>, Error> {
73	    host.flush_cache(true); // clear storage to persist changes, invalidating the cache
74	
75	    unsafe {
76	        RawCall::new_with_value(host, context.value())
77	            .gas(context.gas())
78	            .call(to, data)
79	            .map_err(Error::Revert)
80	    }
81	}
82	
83	#[cfg(test)]
84	mod test {
85	    use alloy_primitives::{Address, U256};
86	    use stylus_core::CallContext;
87	    use stylus_test::TestVM;
88	
89	    use super::*;
90	
91	    #[derive(Clone)]
92	    pub struct MyContract;
93	    impl CallContext for MyContract {
94	        fn gas(&self) -> u64 {
95	            0
96	        }
97	    }
98	    unsafe impl MutatingCallContext for MyContract {
99	        fn value(&self) -> U256 {
100	            U256::from(0)
101	        }
102	    }
103	    impl StaticCallContext for MyContract {}
104	
105	    // Test that sol_interface! correctly decodes multi-value return types.
106	    // This is a regression test for a bug where multi-value returns were
107	    // double-wrapped in a tuple, causing ABI decode panics.
108	    // Uses a dynamic type (string) to ensure the encoding difference is detectable —
109	    // fixed-size-only tuples have identical encoding whether nested or not.
110	    stylus_proc::sol_interface! {
111	        interface IMultiReturn {
112	            function mixed() external view returns (string, uint256);
113	        }
114	    }
115	
116	    #[test]
117	    fn test_sol_interface_multi_return() {
118	        use alloy_sol_types::SolType;
119	
120	        let vm = TestVM::new();
121	        let target = Address::from([3u8; 20]);
122	        let iface = IMultiReturn::new(target);
123	        let ctx = MyContract {};
124	
125	        // Encode the return data as the callee would: flat ABI params (string, uint256)
126	        let return_data = <(
127	            alloy_sol_types::sol_data::String,
128	            alloy_sol_types::sol_data::Uint<256>,
129	        ) as SolType>::abi_encode_params(&(
130	            alloc::string::String::from("hello"),
131	            U256::from(42),
132	        ));
133	
134	        // The calldata for mixed() is just the 4-byte selector (no args)
135	        let selector = &alloy_primitives::keccak256("mixed()")[..4];
136	        vm.mock_static_call(target, selector.to_vec(), Ok(return_data));
137	
138	        let (s, n) = iface.mixed(&vm, ctx).unwrap();
139	        assert_eq!(s, "hello");
140	        assert_eq!(n, U256::from(42));
141	    }
142	
143	    #[test]
144	    fn test_calls() {
145	        let vm = TestVM::new();
146	        let contract = MyContract {};
147	        let target = Address::from([2u8; 20]);
148	        let data = vec![1, 2, 3, 4];
149	        let expected_return = vec![5, 6, 7, 8];
150	
151	        // Mock a regular call.
152	        vm.mock_call(
153	            target,
154	            data.clone(),
155	            U256::ZERO,
156	            Ok(expected_return.clone()),
157	        );
158	
159	        let response = call(&vm, contract.clone(), target, &data).unwrap();
160	        assert_eq!(response, expected_return);
161	        vm.clear_mocks();
162	
163	        // Mock a delegate call.
164	        vm.mock_delegate_call(target, data.clone(), Ok(expected_return.clone()));
165	        let response = unsafe { delegate_call(&vm, contract.clone(), target, &data).unwrap() };
166	        assert_eq!(response, expected_return);
167	        vm.clear_mocks();
168	
169	        // Mock a static call.
170	        vm.mock_static_call(target, data.clone(), Ok(expected_return.clone()));
171	        let response = static_call(&vm, contract.clone(), target, &data).unwrap();
172	        assert_eq!(response, expected_return);
173	    }
174	}
