4	//! Defines a test VM environment for unit testing Stylus contracts.
5	//! Allows for mocking of all host methods defined on the [`stylus_core::host::Host`] trait, such
6	//! as access to storage, messages, block values, and more.
7	//!
8	//! ```ignore
9	//! use stylus_sdk::{alloy_primitives::U256, prelude::*};
10	//!
11	//! #[entrypoint]
12	//! #[storage]
13	//! pub struct MyContract;
14	//!
15	//! #[public]
16	//! impl MyContract {
17	//!     pub fn check_msg_value(&self) -> U256 {
18	//!        self.vm().msg_value()
19	//!     }
20	//! }
21	//!
22	//! #[cfg(test)]
23	//! mod test {
24	//!     use super::*;
25	//!     use stylus_test::*;
26	//!
27	//!     #[test]
28	//!     fn test_my_contract() {
29	//!         let vm = TestVM::default();
30	//!         let contract = MyContract::from(&vm);
31	//!
32	//!         let want = U256::from(100);
33	//!         vm.set_value(want);
34	//!         let got = contract.check_msg_value();
35	//!
36	//!         assert_eq!(want, got);
37	//!     }
38	//! }
39	//! ```
40	
41	use std::{cell::RefCell, rc::Rc, slice};
42	
43	use alloy_primitives::{Address, B256, U256};
44	use alloy_provider::Provider;
45	pub use calls::{errors::Error, MutatingCallContext, StaticCallContext};
46	pub use stylus_core::*;
47	use tokio::runtime::Runtime;
