240	    pub fn mock_call(
241	        &self,
242	        to: Address,
243	        data: Vec<u8>,
244	        value: U256,
245	        return_data: Result<Vec<u8>, Vec<u8>>,
246	    ) {
247	        let mut state = self.state.borrow_mut();
248	        state.return_data = match return_data.clone() {
249	            Ok(data) => data,
250	            Err(data) => data,
251	        };
252	        state.call_returns.insert((to, data, value), return_data);
253	    }
