257	        &self,
258	        to: Address,
259	        data: Vec<u8>,
260	        return_data: Result<Vec<u8>, Vec<u8>>,
261	    ) {
262	        let mut state = self.state.borrow_mut();
263	        state.return_data = match return_data.clone() {
264	            Ok(data) => data,
265	            Err(data) => data,
266	        };
267	
268	        state.delegate_call_returns.insert((to, data), return_data);
269	    }
