54	mod sol {
55	    use alloy_sol_macro::sol;
56	
57	    sol! {
58	        /// Emitted when `new_admin_role` is set as `role`'s admin role, replacing
59	        /// `previous_admin_role`.
60	        ///
61	        /// `DEFAULT_ADMIN_ROLE` is the starting admin for all roles, despite
62	        /// `RoleAdminChanged` not being emitted signaling this.
63	        #[derive(Debug)]
64	        #[allow(missing_docs)]
65	        event RoleAdminChanged(bytes32 indexed role, bytes32 indexed previous_admin_role, bytes32 indexed new_admin_role);
66	        /// Emitted when `account` is granted `role`.
67	        ///
68	        /// `sender` is the account that originated the contract call. This account
69	        /// bears the admin role (for the granted role).
70	        /// Expected in cases where the role was granted using the internal
71	        /// [`AccessControl::grant_role`].
72	        #[derive(Debug)]
73	        #[allow(missing_docs)]
74	        event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender);
75	        /// Emitted when `account` is revoked `role`.
76	        ///
77	        /// `sender` is the account that originated the contract call:
78	        ///   - if using `revoke_role`, it is the admin role bearer.
79	        ///   - if using `renounce_role`, it is the role bearer (i.e. `account`).
80	        #[derive(Debug)]
81	        #[allow(missing_docs)]
82	        event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender);
83	    }
84	
85	    sol! {
86	        /// The `account` is missing a role.
87	        ///
88	        /// * `account` - Account that was found to not be authorized.
89	        /// * `needed_role` - The missing role.
90	        #[derive(Debug)]
91	        #[allow(missing_docs)]
92	        error AccessControlUnauthorizedAccount(address account, bytes32 needed_role);
93	        /// The caller of a function is not the expected one.
94	        ///
95	        /// NOTE: Don't confuse with [`AccessControlUnauthorizedAccount`].
96	        #[derive(Debug)]
97	        #[allow(missing_docs)]
98	        error AccessControlBadConfirmation();
99	    }
100	}
