133	/// Interface for an [`AccessControl`] contract.
134	#[interface_id]
135	#[public]
136	pub trait IAccessControl {
137	    /// The error type associated with this interface implementation.
138	    type Error: Into<alloc::vec::Vec<u8>>;
139	
140	    /// Returns `true` if `account` has been granted `role`.
141	    ///
142	    /// # Arguments
143	    ///
144	    /// * `&self` - Read access to the contract's state.
145	    /// * `role` - The role identifier.
146	    /// * `account` - The account to check for membership.
147	    fn has_role(&self, role: B256, account: Address) -> bool;
148	
149	    /// Checks if [`msg::sender`] has been granted `role`.
150	    ///
151	    /// # Arguments
152	    ///
153	    /// * `&self` - Read access to the contract's state.
154	    /// * `role` - The role identifier.
155	    ///
156	    /// # Errors
157	    ///
158	    /// * [`Error::UnauthorizedAccount`] - If [`msg::sender`] has not been
159	    ///   granted `role`.
160	    fn only_role(&self, role: B256) -> Result<(), Self::Error>;
161	
162	    /// Returns the admin role that controls `role`. See
163	    /// [`IAccessControl::grant_role`] and [`IAccessControl::revoke_role`].
164	    ///
165	    /// To change a role's admin, use [`AccessControl::_set_role_admin`].
166	    ///
167	    /// # Arguments
168	    ///
169	    /// * `&self` - Read access to the contract's state.
170	    /// * `role` - The role identifier.
171	    fn get_role_admin(&self, role: B256) -> B256;
172	
173	    /// Grants `role` to `account`.
174	    ///
175	    /// If `account` had not been already granted `role`, emits a
176	    /// [`RoleGranted`] event.
177	    ///
178	    /// # Arguments
179	    ///
180	    /// * `&mut self` - Write access to the contract's state.
181	    /// * `role` - The role identifier.
182	    /// * `account` - The account which will be granted the role.
183	    ///
184	    /// # Errors
185	    ///
186	    /// * [`Error::UnauthorizedAccount`] - If [`msg::sender`] has not been
187	    ///   granted `role`.
188	    ///
189	    /// # Events
190	    ///
191	    /// * [`RoleGranted`]
192	    fn grant_role(
193	        &mut self,
194	        role: B256,
195	        account: Address,
196	    ) -> Result<(), Self::Error>;
197	
198	    /// Revokes `role` from `account`.
199	    ///
200	    /// If `account` had been granted `role`, emits a [`RoleRevoked`] event.
201	    ///
202	    /// # Arguments
203	    ///
204	    /// * `&mut self` - Write access to the contract's state.
205	    /// * `role` - The role identifier.
206	    /// * `account` - The account which will be revoked the role.
207	    ///
208	    /// # Errors
209	    ///
210	    /// * [`Error::UnauthorizedAccount`] - If [`msg::sender`] has not been
211	    ///   granted `role`.
212	    ///
213	    /// # Events
214	    ///
215	    /// * [`RoleRevoked`].
216	    fn revoke_role(
217	        &mut self,
218	        role: B256,
219	        account: Address,
220	    ) -> Result<(), Self::Error>;
221	
222	    /// Revokes `role` from the calling account.
223	    ///
224	    /// Roles are often managed via [`Self::grant_role`] and
225	    /// [`Self::revoke_role`]: this function's purpose is to provide a mechanism
226	    /// for accounts to lose their privileges if they are compromised (such as
227	    /// when a trusted device is misplaced).
228	    ///
229	    /// # Arguments
230	    ///
231	    /// * `&mut self` - Write access to the contract's state.
232	    /// * `role` - The role identifier.
233	    /// * `confirmation` - The account which will be revoked the role.
234	    ///
235	    /// # Errors
236	    ///
237	    /// * [`Error::BadConfirmation`]  - If [`msg::sender`] is not the
238	    ///   `confirmation` address.
239	    ///
240	    /// # Events
241	    ///
242	    /// * [`RoleRevoked`] - If the calling account has its `role` revoked.
243	    fn renounce_role(
244	        &mut self,
245	        role: B256,
246	        confirmation: Address,
247	    ) -> Result<(), Self::Error>;
248	}
