254	#[public]
255	impl IAccessControl for AccessControl {
256	    type Error = Error;
257	
258	    fn has_role(&self, role: B256, account: Address) -> bool {
259	        self.roles.getter(role).has_role.get(account)
260	    }
261	
262	    fn only_role(&self, role: B256) -> Result<(), Self::Error> {
263	        self._check_role(role, self.vm().msg_sender())
264	    }
265	
266	    fn get_role_admin(&self, role: B256) -> B256 {
267	        self.roles.getter(role).admin_role.get()
268	    }
269	
270	    fn grant_role(
271	        &mut self,
272	        role: B256,
273	        account: Address,
274	    ) -> Result<(), Self::Error> {
275	        let admin_role = self.get_role_admin(role);
276	        self.only_role(admin_role)?;
277	        self._grant_role(role, account);
278	        Ok(())
279	    }
280	
281	    fn revoke_role(
282	        &mut self,
283	        role: B256,
284	        account: Address,
285	    ) -> Result<(), Self::Error> {
286	        let admin_role = self.get_role_admin(role);
287	        self.only_role(admin_role)?;
288	        self._revoke_role(role, account);
289	        Ok(())
290	    }
291	
292	    fn renounce_role(
293	        &mut self,
294	        role: B256,
295	        confirmation: Address,
296	    ) -> Result<(), Self::Error> {
297	        if self.vm().msg_sender() != confirmation {
298	            return Err(Error::BadConfirmation(
299	                AccessControlBadConfirmation {},
300	            ));
301	        }
302	
303	        self._revoke_role(role, confirmation);
304	        Ok(())
305	    }
306	}
