308	impl AccessControl {
309	    /// The default admin role. `[0; 32]` by default.
310	    pub const DEFAULT_ADMIN_ROLE: [u8; 32] = [0; 32];
311	
312	    /// Sets `admin_role` as `role`'s admin role.
313	    ///
314	    /// # Arguments
315	    ///
316	    /// * `&mut self` - Write access to the contract's state.
317	    /// * `role` - The identifier of the role we are changing the admin to.
318	    /// * `new_admin_role` - The new admin role.
319	    ///
320	    /// # Events
321	    ///
322	    /// * [`RoleAdminChanged`].
323	    pub fn _set_role_admin(&mut self, role: B256, new_admin_role: B256) {
324	        let previous_admin_role = self.get_role_admin(role);
325	        self.roles.setter(role).admin_role.set(new_admin_role);
326	        self.vm().log(RoleAdminChanged {
327	            role,
328	            previous_admin_role,
329	            new_admin_role});
330	    }
331	
332	    /// Checks if `account` has been granted `role`.
333	    ///
334	    /// # Arguments
335	    ///
336	    /// * `&self` - Read access to the contract's state.
337	    /// * `role` - The role identifier.
338	    /// * `account` - The account to check for membership.
339	    ///
340	    /// # Errors
341	    ///
342	    /// * [`Error::UnauthorizedAccount`] - If [`msg::sender`] has not been
343	    ///   granted `role`.
344	    pub fn _check_role(
345	        &self,
346	        role: B256,
347	        account: Address,
348	    ) -> Result<(), Error> {
349	        if !self.has_role(role, account) {
350	            return Err(Error::UnauthorizedAccount(
351	                AccessControlUnauthorizedAccount { account, needed_role: role },
352	            ));
353	        }
354	
355	        Ok(())
356	    }
357	
358	    /// Attempts to grant `role` to `account` and returns a boolean indicating
359	    /// if `role` was granted.
360	    ///
361	    /// Internal function without access restriction.
362	    ///
363	    /// # Arguments
364	    ///
365	    /// * `&mut self` - Write access to the contract's state.
366	    /// * `role` - The role identifier.
367	    /// * `account` - The account which will be granted the role.
368	    ///
369	    /// # Events
370	    ///
371	    /// * [`RoleGranted`].
372	    pub fn _grant_role(&mut self, role: B256, account: Address) -> bool {
373	        if self.has_role(role, account) {
374	            false
375	        } else {
376	            self.roles.setter(role).has_role.insert(account, true);
377	            self.vm().log(RoleGranted { role, account, sender: self.vm().msg_sender() });
378	            true
379	        }
380	    }
381	
382	    /// Attempts to revoke `role` from `account` and returns a boolean
383	    /// indicating if `role` was revoked.
384	    ///
385	    /// Internal function without access restriction.
386	    ///
387	    /// # Arguments
388	    ///
389	    /// * `&mut self` - Write access to the contract's state.
390	    /// * `role` - The role identifier.
391	    /// * `account` - The account which will be granted the role.
392	    ///
393	    /// # Events
394	    ///
395	    /// * [`RoleRevoked`].
396	    pub fn _revoke_role(&mut self, role: B256, account: Address) -> bool {
397	        if self.has_role(role, account) {
398	            self.roles.setter(role).has_role.insert(account, false);
399	            self.vm().log(RoleRevoked { role, account, sender: self.vm().msg_sender() });
400	            true
401	        } else {
402	            false
403	        }
404	    }
405	}
