76	impl AccessControlEnumerable {
77	    /// Returns the members of `role`.
78	    ///
79	    /// # WARNING
80	    ///
81	    /// This operation will copy the entire storage to memory, which can be
82	    /// quite expensive. This is designed to mostly be used by view
83	    /// accessors that are queried without any gas fees. Developers should keep
84	    /// in mind that this function has an unbounded cost, and using it as
85	    /// part of a state-changing function may render the function uncallable
86	    /// if the set grows to a point where copying to memory consumes too much
87	    /// gas to fit in a block.
88	    ///
89	    /// # Arguments
90	    ///
91	    /// * `&self` - Read access to the contract's state.
92	    /// * `role` - The role identifier.
