100	impl IAccessControlEnumerable for AccessControlEnumerable {
101	    type Error = Error;
102	
103	    fn get_role_member(
104	        &self,
105	        role: B256,
106	        index: U256,
107	    ) -> Result<Address, Self::Error> {
108	        let members = self.role_members.get(role);
109	        match members.at(index) {
110	            Some(member) => Ok(member),
111	            None => {
112	                Err(Error::OutOfBounds(AccessControlEnumerableOutOfBounds {
113	                    role,
114	                    index}))
115	            }
116	        }
117	    }
118	
119	    fn get_role_member_count(&self, role: B256) -> U256 {
120	        self.role_members.get(role).length()
121	    }
122	}
