124	impl AccessControlEnumerable {
125	    /// Extension of [`AccessControl::_grant_role`] that adds the `account` to
126	    /// `role`'s members list.
127	    #[allow(clippy::missing_errors_doc)]
128	    pub fn _grant_role(
129	        &mut self,
130	        role: B256,
131	        account: Address,
132	        access_control: &mut AccessControl,
133	    ) -> bool {
134	        let granted = access_control._grant_role(role, account);
135	
136	        if granted {
137	            self.role_members.setter(role).add(account);
138	        }
139	
140	        granted
141	    }
142	
143	    /// Extension of [`AccessControl::_revoke_role`] that removes the `account`
144	    /// from `role`'s members list.
145	    #[allow(clippy::missing_errors_doc)]
146	    pub fn _revoke_role(
147	        &mut self,
148	        role: B256,
149	        account: Address,
150	        access_control: &mut AccessControl,
151	    ) -> bool {
152	        let revoked = access_control._revoke_role(role, account);
153	
154	        if revoked {
155	            self.role_members.setter(role).remove(account);
156	        }
157	
158	        revoked
159	    }
160	}
