35	const STYLUS_PUBLIC_TAG_CHECK_FN_NAME: &str =
36	    "__stylus_trait_and_impl_must_be_tagged_with_public_macro";
37	
38	/// Implementation of the [`#[public]`][crate::public] macro.
39	///
40	/// This implementation performs the following steps:
41	/// - Parse the input as [`syn::ItemImpl`]
42	/// - Generate AST items within a [`PublicImpl`]
43	/// - Expand those AST items into tokens for output
44	pub fn public(attr: TokenStream, input: TokenStream) -> TokenStream {
45	    check_attr_is_empty(attr);
46	
47	    let mut output = proc_macro2::TokenStream::new();
48	
49	    let item = parse_macro_input!(input as syn::Item);
50	    match item {
51	        syn::Item::Impl(mut item_impl) => {
52	            let public_impl = PublicImpl::<Extension>::from(&mut item_impl);
53	            add_stylus_public_tag_check_fn_definition(&mut item_impl);
54	            output.extend(quote! {
55	                #[cfg(not(feature = "contract-client-gen"))]
56	                #[allow(dead_code)]
57	            });
58	            output.extend(item_impl.into_token_stream());
59	            public_impl.to_tokens(&mut output);
60	        }
61	        syn::Item::Trait(mut item_trait) => {
62	            let public_trait = PublicTrait::from(&mut item_trait);
63	            add_stylus_public_tag_check_fn_declaration(&mut item_trait);
64	            output.extend(quote! {
65	                #[cfg(not(feature = "contract-client-gen"))]
66	                #[allow(dead_code)]
67	            });
68	            output.extend(item_trait.into_token_stream());
69	            public_trait.to_tokens(&mut output);
70	        }
71	        _ => {
72	            emit_error!(item.span(), "expected impl or trait");
73	        }
74	    }
75	    output.into()
76	}
77	
78	fn add_stylus_public_tag_check_fn_declaration(item_trait: &mut syn::ItemTrait) {
79	    let fn_name = syn::Ident::new(STYLUS_PUBLIC_TAG_CHECK_FN_NAME, item_trait.span());
80	    let item: syn::TraitItem = parse_quote! {
81	        fn #fn_name(&self);
82	    };
83	    item_trait.items.push(item);
84	}
85	
86	fn add_stylus_public_tag_check_fn_definition(item_impl: &mut syn::ItemImpl) {
87	    let fn_name = syn::Ident::new(STYLUS_PUBLIC_TAG_CHECK_FN_NAME, item_impl.span());
88	    let item: syn::ImplItem = parse_quote! {
89	        fn #fn_name(&self) {
90	        }
91	    };
92	    item_impl.items.push(item);
93	}
