95	impl From<&mut syn::ItemTrait> for PublicTrait {
96	    fn from(node: &mut syn::ItemTrait) -> Self {
97	        let ident = node.ident.clone();
98	
99	        let funcs = node
100	            .items
101	            .iter_mut()
102	            .filter_map(|item| match item {
103	                syn::TraitItem::Fn(func) => Some(PublicFn::from(func)),
104	                syn::TraitItem::Const(_) => {
105	                    emit_error!(item, "unsupported trait item");
106	                    None
107	                }
108	                _ => {
109	                    // allow other item types
110	                    None
111	                }
112	            })
113	            .collect();
114	
115	        let (generic_params, where_clause) = get_generics(&node.generics);
116	
117	        // Extract associated types
118	        let mut associated_types = Vec::new();
119	        for item in &node.items {
120	            if let syn::TraitItem::Type(type_item) = item {
121	                associated_types.push((type_item.ident.clone(), type_item.bounds.clone()));
122	            }
123	        }
124	
125	        Self {
126	            ident,
127	            generic_params,
128	            where_clause,
129	            funcs,
130	            associated_types,
131	        }
132	    }
133	}
