135	impl ToTokens for PublicTrait {
136	    fn to_tokens(&self, tokens: &mut proc_macro2::TokenStream) {
137	        tokens.extend(self.contract_client_gen());
138	        // Emit collision checks for trait definitions too, so that library crates
139	        // defining a #[public] trait without a corresponding impl still get checked.
140	        // When both the trait and its impl exist in the same crate, the compiler will
141	        // evaluate redundant (but harmless) duplicate const assertions; on a collision,
142	        // the user may see the error reported twice. Deduplication is not feasible because
143	        // the trait and impl are processed by separate proc-macro invocations that cannot
144	        // communicate.
145	        //
146	        // Skip checks for generic traits: the generic type parameters would not be in
147	        // scope in the emitted `const _: ()` items. The concrete `impl Trait<...> for S`
148	        // block will still emit its own collision checks with the resolved types.
149	        if self.generic_params.is_empty() {
150	            for check in types::selector_collision_checks(&self.funcs) {
151	                check.to_tokens(tokens);
152	            }
153	        }
154	    }
155	}
156	
157	impl ToTokens for PublicImpl {
158	    fn to_tokens(&self, tokens: &mut proc_macro2::TokenStream) {
159	        tokens.extend(self.struct_for_export_abi());
160	        tokens.extend(self.contract_client_gen());
161	        tokens.extend(self.print_from_args_fn());
162	        // Skip collision checks for generic impl blocks: the emitted `const` items
163	        // would reference type parameters that are not in scope at module level.
164	        if self.generic_params.is_empty() {
165	            for check in types::selector_collision_checks(&self.funcs) {
166	                check.to_tokens(tokens);
167	            }
168	        }
169	        self.impl_router().to_tokens(tokens);
170	        Extension::codegen(self).to_tokens(tokens);
171	    }
172	}
