174	impl From<&mut syn::ItemImpl> for PublicImpl {
175	    fn from(node: &mut syn::ItemImpl) -> Self {
176	        // parse traits from #[implements(...)] attribute
177	        let mut implements = Vec::new();
178	        if let Some(attr) = consume_attr::<attrs::Implements>(&mut node.attrs, "implements") {
179	            implements.extend(attr.types);
180	        }
181	        let funcs = node
182	            .items
183	            .iter_mut()
184	            .filter_map(|item| match item {
185	                syn::ImplItem::Fn(func) => Some(PublicFn::from(func)),
186	                syn::ImplItem::Const(_) => {
187	                    emit_error!(item, "unsupported impl item");
188	                    None
189	                }
190	                _ => {
191	                    // allow other item types
192	                    None
193	                }
194	            })
195	            .collect();
196	
197	        let self_ty = (*node.self_ty).clone();
198	        let (generic_params, where_clause) = get_generics(&node.generics);
199	        let trait_ = match &node.trait_ {
200	            Some((_, trait_, _)) => Some(trait_.clone()),
201	            _ => None,
202	        };
203	
204	        // Extract associated types from the impl items
205	        let mut associated_types = Vec::new();
206	        for item in &node.items {
207	            if let syn::ImplItem::Type(type_item) = item {
208	                associated_types.push((type_item.ident.clone(), type_item.ty.clone()));
209	            }
210	        }
211	
212	        #[allow(clippy::let_unit_value)]
213	        let extension = <Extension as InterfaceExtension>::build(node);
214	        Self {
215	            self_ty,
216	            generic_params,
217	            where_clause,
