103	#[derive(Debug)]
104	struct Storage {
105	    name: syn::Ident,
106	    generics: syn::Generics,
107	    fields: Vec<StorageField>,
108	}
109	
110	impl Storage {
111	    fn item_impl(&self) -> syn::ItemImpl {
112	        let name = &self.name;
113	        let (impl_generics, ty_generics, where_clause) = self.generics.split_for_impl();
114	        let size = TokenStream::from_iter(self.fields.iter().map(StorageField::size));
115	        parse_quote! {
116	            #[cfg(not(feature = "contract-client-gen"))]
117	            impl #impl_generics #name #ty_generics #where_clause {
118	                const fn required_slots() -> usize {
119	                    use stylus_sdk::storage;
120	                    let mut total: usize = 0;
121	                    let mut space: usize = 32;
122	                    #size
123	                    if space != 32 || total == 0 {
124	                        total += 1;
125	                    }
126	                    total
127	                }
128	            }
129	        }
130	    }
131	
132	    fn impl_storage_type(&self) -> syn::ItemImpl {
133	        let name = &self.name;
134	        let (impl_generics, ty_generics, where_clause) = self.generics.split_for_impl();
135	        let init = Punctuated::<syn::FieldValue, Token![,]>::from_iter(
136	            self.fields.iter().filter_map(StorageField::init),
137	        );
138	        parse_quote! {
139	            #[cfg(not(feature = "contract-client-gen"))]
140	            impl #impl_generics stylus_sdk::storage::StorageType for #name #ty_generics #where_clause {
141	                type Wraps<'a> = stylus_sdk::storage::StorageGuard<'a, Self> where Self: 'a;
142	                type WrapsMut<'a> = stylus_sdk::storage::StorageGuardMut<'a, Self> where Self: 'a;
143	
144	                // start a new word
145	                const SLOT_BYTES: usize = 32;
146	                const REQUIRED_SLOTS: usize = Self::required_slots();
147	
148	                unsafe fn new(mut root: stylus_sdk::alloy_primitives::U256, offset: u8, host: stylus_sdk::host::VM) -> Self {
149	                    use stylus_sdk::{storage, alloy_primitives};
150	                    debug_assert!(offset == 0);
151	
152	                    let mut space: usize = 32;
153	                    let mut slot: usize = 0;
154	                    let accessor = Self {
155	                        #STYLUS_HOST_FIELD: host.clone(),
156	                        #[cfg(feature = "contract-client-gen")]
157	                        #STYLUS_CONTRACT_ADDRESS_FIELD: stylus_sdk::alloy_primitives::Address::ZERO,
158	                        #init
159	                    };
160	                    accessor
161	                }
162	
163	                fn load<'s>(self) -> Self::Wraps<'s> {
164	                    stylus_sdk::storage::StorageGuard::new(self)
165	                }
166	
167	                fn load_mut<'s>(self) -> Self::WrapsMut<'s> {
168	                    stylus_sdk::storage::StorageGuardMut::new(self)
169	                }
170	            }
171	        }
172	    }
173	
174	    fn impl_host_access(&self) -> syn::ItemImpl {
175	        let name = &self.name;
176	        let (impl_generics, ty_generics, where_clause) = self.generics.split_for_impl();
177	
178	        parse_quote! {
179	            #[cfg(not(feature = "contract-client-gen"))]
180	            impl #impl_generics stylus_sdk::stylus_core::HostAccess for #name #ty_generics #where_clause {
181	                type Host = stylus_sdk::host::VM;
182	
183	                fn vm(&self) -> &Self::Host {
184	                    &self.__stylus_host
185	                }
186	            }
187	        }
188	    }
189	
190	    fn impl_value_denier(&self) -> syn::ItemImpl {
191	        let name = &self.name;
192	        let (impl_generics, ty_generics, where_clause) = self.generics.split_for_impl();
193	        parse_quote! {
194	            #[cfg(not(feature = "contract-client-gen"))]
195	            impl #impl_generics stylus_sdk::stylus_core::host::ValueDenier for #name #ty_generics #where_clause {
196	                fn deny_value(&self, method_name: &str) -> Result<(), Vec<u8>> {
197	                    if self.vm().msg_value() == stylus_sdk::alloy_primitives::U256::ZERO {
198	                        return Ok(());
199	                    }
200	                    stylus_sdk::console!("method {method_name} not payable");
201	                    Err(vec![])
202	                }
203	            }
204	        }
205	    }
206	
207	    fn impl_constructor_guard(&self) -> syn::ItemImpl {
208	        let name = &self.name;
209	        let (impl_generics, ty_generics, where_clause) = self.generics.split_for_impl();
210	        parse_quote! {
211	            #[cfg(not(feature = "contract-client-gen"))]
212	            impl #impl_generics stylus_sdk::stylus_core::host::ConstructorGuard for #name #ty_generics #where_clause {
213	                fn check_constructor_slot(&self) -> Result<(), Vec<u8>> {
214	                    let mut slot = unsafe {
215	                        stylus_sdk::storage::StorageBool::new(
216	                            stylus_sdk::abi::internal::CONSTRUCTOR_EXECUTED_SLOT,
217	                            0,
218	                            self.__stylus_host.clone()
219	                        )
220	                    };
221	                    if slot.get() {
222	                        stylus_sdk::console!("constructor already called");
223	                        return Err(alloc::vec![]);
224	                    }
225	                    slot.set(true);
226	                    Ok(())
227	                }
228	            }
229	        }
230	    }
231	
232	    fn impl_from_vm(&self) -> Option<syn::ItemImpl> {
233	        cfg_if::cfg_if! {
234	            if #[cfg(feature = "stylus-test")] {
235	                let name = &self.name;
236	                let (_, ty_generics, where_clause) = self.generics.split_for_impl();
237	                let mut new_generics = self.generics.clone();
238	                let host_param =
239	                    parse_quote!(__StylusHostType: stylus_sdk::stylus_core::Host + Clone + 'static);
240	                new_generics.params.push(host_param);
241	                let (impl_generics, _, _) = new_generics.split_for_impl();
242	                Some(parse_quote! {
243	                    #[cfg(not(feature = "contract-client-gen"))]
244	                    impl #impl_generics From<&__StylusHostType> for #name #ty_generics #where_clause {
245	                        fn from(host: &__StylusHostType) -> Self {
246	                            unsafe {
247	                                Self::new(
248	                                    stylus_sdk::alloy_primitives::U256::ZERO,
249	                                    0,
250	                                    stylus_sdk::host::VM {
251	                                        host: alloc::boxed::Box::new(host.clone()),
252	                                    },
253	                                )
254	                            }
255	                        }
256	                    }
257	                })
258	            } else {
259	                None
260	            }
261	        }
262	    }
263	
264	    fn impl_vm_access(&self) -> syn::ItemImpl {
265	        let name = &self.name;
266	        let (impl_generics, ty_generics, where_clause) = self.generics.split_for_impl();
267	        parse_quote! {
268	            #[cfg(not(feature = "contract-client-gen"))]
269	            impl #impl_generics stylus_sdk::host::VMAccess for #name #ty_generics #where_clause {
270	                unsafe fn raw_vm(&self) -> stylus_sdk::host::VM {
271	                    self.__stylus_host.clone()
272	                }
273	            }
274	        }
275	    }
276	}
