278	impl From<&mut syn::ItemStruct> for Storage {
279	    fn from(node: &mut syn::ItemStruct) -> Self {
280	        let name = node.ident.clone();
281	        let generics = node.generics.clone();
282	        let fields = node
283	            .fields
284	            .iter_mut()
285	            .enumerate()
286	            .filter_map(|(idx, field)| {
287	                if let syn::Type::Path(..) = &field.ty {
288	                    Some(StorageField::new(idx, field))
289	                } else {
290	                    None
291	                }
292	            })
293	            .collect();
294	        Self {
295	            name,
296	            generics,
297	            fields,
298	        }
299	    }
300	}
