302	impl ToTokens for Storage {
303	    fn to_tokens(&self, tokens: &mut TokenStream) {
304	        self.item_impl().to_tokens(tokens);
305	        self.impl_storage_type().to_tokens(tokens);
306	        self.impl_host_access().to_tokens(tokens);
307	        self.impl_value_denier().to_tokens(tokens);
308	        self.impl_constructor_guard().to_tokens(tokens);
309	        self.impl_from_vm().to_tokens(tokens);
310	        self.impl_vm_access().to_tokens(tokens);
311	        for field in &self.fields {
312	            field.impl_borrow(&self.name).to_tokens(tokens);
313	            field.impl_borrow_mut(&self.name).to_tokens(tokens);
314	        }
315	    }
316	}
