318	#[derive(Debug)]
319	struct StorageField {
320	    name: Option<syn::Ident>,
321	    ty: syn::Type,
322	    accessor: syn::Member,
323	    borrow: bool,
324	}
325	
326	impl StorageField {
327	    fn new(idx: usize, field: &mut syn::Field) -> Self {
328	        check_type(field);
329	        let name = field.ident.clone();
330	        let ty = field.ty.clone();
331	        let accessor = field
332	            .ident
333	            .clone()
334	            .map(syn::Member::from)
335	            .unwrap_or_else(|| idx.into());
336	
337	        let borrow = consume_flag(&mut field.attrs, "borrow");
338	        Self {
339	            name,
340	            ty,
341	            accessor,
342	            borrow,
343	        }
344	    }
345	
346	    fn init(&self) -> Option<syn::FieldValue> {
347	        let Some(ident) = &self.name else {
348	            return None;
349	        };
350	        if *ident == STYLUS_HOST_FIELD.as_ident() {
351	            return None;
352	        }
353	        if *ident == STYLUS_CONTRACT_ADDRESS_FIELD.as_ident() {
354	            return None;
355	        }
356	        let ty = &self.ty;
357	        Some(parse_quote! {
358	            #ident: {
359	                let bytes = <#ty as storage::StorageType>::SLOT_BYTES;
360	                let words = <#ty as storage::StorageType>::REQUIRED_SLOTS;
361	                if space < bytes {
362	                    space = 32;
363	                    slot += 1;
364	                }
365	                space -= bytes;
366	
367	                let root = root + alloy_primitives::U256::from(slot);
368	                let field = <#ty as storage::StorageType>::new(root, space as u8, host.clone());
369	                if words > 0 {
370	                    slot += words;
371	                    space = 32;
372	                }
373	                field
374	            }
375	        })
376	    }
377	
378	    fn size(&self) -> TokenStream {
379	        let ty = &self.ty;
380	        let Some(ident) = &self.name else {
381	            return quote! {};
382	        };
383	        if *ident == STYLUS_HOST_FIELD.as_ident() {
384	            return quote! {};
385	        }
386	        if *ident == STYLUS_CONTRACT_ADDRESS_FIELD.as_ident() {
387	            return quote! {};
388	        }
389	        quote! {
390	            let bytes = <#ty as storage::StorageType>::SLOT_BYTES;
391	            let words = <#ty as storage::StorageType>::REQUIRED_SLOTS;
392	
393	            if space < bytes {
394	                space = 32;
395	                total += 1;
396	            }
397	            space -= bytes;
398	
399	            if words > 0 {
400	                total += words;
401	                space = 32;
402	            }
403	        }
404	    }
405	
406	    fn impl_borrow(&self, name: &syn::Ident) -> Option<syn::ItemImpl> {
407	        let Self { ty, accessor, .. } = self;
408	        self.borrow.then(|| {
409	            parse_quote! {
410	                #[cfg(not(feature = "contract-client-gen"))]
411	                impl core::borrow::Borrow<#ty> for #name {
412	                    fn borrow(&self) -> &#ty {
413	                        &self.#accessor
414	                    }
415	                }
416	            }
417	        })
418	    }
419	
420	    fn impl_borrow_mut(&self, name: &syn::Ident) -> Option<syn::ItemImpl> {
421	        let Self { ty, accessor, .. } = self;
422	        self.borrow.then(|| {
423	            parse_quote! {
424	                #[cfg(not(feature = "contract-client-gen"))]
425	                impl core::borrow::BorrowMut<#ty> for #name {
426	                    fn borrow_mut(&mut self) -> &mut #ty {
427	                        &mut self.#accessor
428	                    }
429	                }
430	            }
431	        })
432	    }
433	}
434	
435	fn check_type(field: &syn::Field) {
436	    let Type::Path(ty) = &field.ty else {
437	        unreachable!();
438	    };
439	
440	    let path = &ty.path.segments.last().unwrap().ident;
441	    let not_supported = format!("Type `{path}` not supported for EVM state storage");
442	
443	    match path.to_string().as_str() {
444	        x @ ("u8" | "u16" | "u32" | "u64" | "u128" | "i8" | "i16" | "i32" | "i64" | "i128"
445	        | "U8" | "U16" | "U32" | "U64" | "U128" | "I8" | "I16" | "I32" | "I64" | "I128") => {
446	            emit_error!(
447	                &field,
448	                "{not_supported}. Instead try `Storage{}`.",
449	                x.to_uppercase()
450	            );
451	        }
452	        "usize" => emit_error!(&field, "{not_supported}."),
453	        "isize" => emit_error!(&field, "{not_supported}."),
454	        "bool" => emit_error!(&field, "{not_supported}. Instead try `StorageBool`."),
455	        "f32" | "f64" => emit_error!(&field, "{not_supported}. Consider fixed-point arithmetic."),
456	        _ => {}
457	    }
458	}
