16	// Define some persistent storage using the Solidity ABI.
17	// `Counter` will be the entrypoint.
18	sol_storage! {
19	    #[entrypoint]
20	    pub struct Counter {
21	        uint256 number;
22	        address owner;
23	        uint256 last_updated;
24	    }
25	}
26	
27	// Define events
28	sol! {
29	event CounterUpdated(address indexed user, uint256 prev_value, uint256 new_value);
30	}
31	
32	/// Declare that `Counter` is a contract with the following external methods.
33	#[public]
34	impl Counter {
35	    pub fn calling_console_doesnt_panic_in_test(&self) {
36	        console!("console called successfully");
37	    }
38	    pub fn owner(&self) -> Address {
39	        self.owner.get()
40	    }
41	    pub fn number(&self) -> U256 {
42	        self.number.get()
43	    }
44	    pub fn last_updated(&self) -> U256 {
45	        self.last_updated.get()
46	    }
47	    /// Sets a number in storage to a user-specified value.
48	    pub fn set_number(&mut self, new_number: U256) {
49	        let prev = self.number.get();
50	        self.number.set(new_number);
51	        // Update the last updated timestamp.
52	        self.last_updated
53	            .set(U256::from(self.vm().block_timestamp()));
54	        // Emit an event
55	        self.vm().log(CounterUpdated {
56	            user: self.vm().msg_sender(),
57	            prev_value: prev,
58	            new_value: self.number.get(),
59	        });
60	    }
61	    /// Multiplies `number` by `new_number` and updates its value in storage.
62	    pub fn mul_number(&mut self, new_number: U256) {
63	        self.number.set(new_number * self.number.get());
64	        let prev = self.number.get();
65	        // Update the last updated timestamp.
66	        self.last_updated
67	            .set(U256::from(self.vm().block_timestamp()));
68	        // Emit an event
69	        self.vm().log(CounterUpdated {
70	            user: self.vm().msg_sender(),
71	            prev_value: prev,
72	            new_value: self.number.get(),
73	        });
74	    }
75	    /// Increments `number` by `new_number` and updates its value in storage.
76	    pub fn add_number(&mut self, new_number: U256) {
77	        self.number.set(new_number + self.number.get());
78	        let prev = self.number.get();
79	        // Update the last updated timestamp.
80	        self.last_updated
81	            .set(U256::from(self.vm().block_timestamp()));
82	        // Emit an event
83	        self.vm().log(CounterUpdated {
84	            user: self.vm().msg_sender(),
85	            prev_value: prev,
86	            new_value: self.number.get(),
87	        });
88	    }
89	    /// Increments `number` by 1 and updates its value in storage.
90	    pub fn increment(&mut self) {
91	        // Increment the number in storage.
92	        let prev = self.number.get();
93	        self.set_number(prev + U256::from(1));
94	        // Update the last updated timestamp.
95	        self.last_updated
96	            .set(U256::from(self.vm().block_timestamp()));
97	        // Emit an event
98	        self.vm().log(CounterUpdated {
99	            user: self.vm().msg_sender(),
100	            prev_value: prev,
101	            new_value: self.number.get(),
102	        });
103	    }
104	    /// Decrements `number` and updates its value in storage.
105	    /// Returns an error if the number is already zero.
106	    pub fn decrement(&mut self) -> Result<(), Vec<u8>> {
107	        let prev = self.number.get();
108	        if prev == U256::ZERO {
109	            return Err(b"Counter cannot go below zero".to_vec());
110	        }
111	
112	        self.number.set(prev - U256::from(1));
113	        // Update the last updated timestamp.
114	        self.last_updated
115	            .set(U256::from(self.vm().block_timestamp()));
116	        // Emit an event
117	        self.vm().log(CounterUpdated {
118	            user: self.vm().msg_sender(),
119	            prev_value: prev,
120	            new_value: self.number.get(),
121	        });
122	
123	        Ok(())
124	    }
125	    /// Adds the wei value from msg_value to the number in storage.
126	    #[payable]
127	    pub fn add_from_msg_value(&mut self) {
128	        let prev = self.number.get();
129	        self.set_number(prev + self.vm().msg_value());
130	        // Update the last updated timestamp.
131	        self.last_updated
132	            .set(U256::from(self.vm().block_timestamp()));
133	        // Emit an event
134	        self.vm().log(CounterUpdated {
135	            user: self.vm().msg_sender(),
136	            prev_value: prev,
137	            new_value: self.number.get(),
138	        });
139	    }
140	    // External call example
141	    pub fn call_external_contract(
142	        &mut self,
143	        target: Address,
144	        data: Vec<u8>,
145	    ) -> Result<Vec<u8>, Vec<u8>> {
146	        if self.owner.get() != self.vm().msg_sender() {
147	            return Err(b"Only owner can call this function".to_vec());
148	        }
149	        let context = Call::new_mutating(self);
150	        let return_data = call(self.vm(), context, target, &data)
151	            .map_err(|err| format!("{err:?}").as_bytes().to_vec())?;
152	        Ok(return_data)
153	    }
154	    /// Transfers ownership of the contract to a new address.
155	    pub fn transfer_ownership(&mut self, new_owner: Address) -> Result<(), Vec<u8>> {
156	        if self.owner.get() == Address::ZERO {
157	            self.owner.set(new_owner);
158	            return Ok(());
159	        }
160	        // Check if the owner is already set.
161	        if self.owner.get() != self.vm().msg_sender() {
162	            return Err(b"Only owner can call this function".to_vec());
163	        }
164	        if new_owner == Address::ZERO {
165	            return Err(b"Cannot transfer to zero address".to_vec());
166	        }
167	        self.owner.set(new_owner);
168	        Ok(())
169	    }
170	}
