422	// Writing your Own Custom TestVM
423	// A TestVM is a simple struct implemented in the stylus-test crate that implements the Host trait
424	// from stylus_core::host::Host. Anyone can implement the trait and allow for rich testing
425	// experiences for Stylus contracts. The TestVM is not the only way to unit test your projects, as
426	// you can extend or implement your own.
427	
428	// Here’s a “general-purpose” extension to TestVM that is just a way to track how many times someone
429	// has called into mock_call, so you can assert on how many external calls you set up:
430	// This is a simple example, but you can imagine more complex scenarios where you might want to
431	// track how many times a function was called, or what the arguments were, etc. You can also use
432	// this to set up more complex test cases where you need to mock multiple calls with different
433	// arguments.
434	
435	#[cfg(test)]
436	mod custom_vm_tests {
437	    use alloy_primitives::Address;
438	    use stylus_sdk::testing::TestVM;
439	
440	    use super::*;
441	
442	    /// A thin wrapper around TestVM that counts how many times
443	    /// `mock_call` has been invoked.
444	    pub struct CustomVM {
445	        inner: TestVM,
446	        mock_call_count: usize,
447	    }
448	
449	    impl CustomVM {
450	        /// Start with the default TestVM
451	        pub fn new() -> Self {
452	            Self {
453	                inner: TestVM::default(),
454	                mock_call_count: 0,
455	            }
456	        }
457	        /// **Wrapped** mock_call: increments our counter, then delegates.
458	        pub fn mock_call(&mut self, target: Address, data: Vec<u8>, ret: Result<Vec<u8>, Vec<u8>>) {
459	            self.mock_call_count += 1;
460	            self.inner.mock_call(target, data, U256::ZERO, ret);
461	        }
462	
463	        /// New helper: how many mocks have been defined so far?
464	        pub fn mock_call_count(&self) -> usize {
465	            self.mock_call_count
466	        }
467	
468	        /// Expose the raw TestVM when you need it for `Counter::from(&…)`
469	        pub fn inner(&self) -> &TestVM {
470	            &self.inner
471	        }
472	    }
473	
474	    #[test]
475	    fn test_tracking_number_of_mocks() {
476	        // 1) Build our custom VM wrapper
477	        let mut vm = CustomVM::new();
478	
479	        // 2) Deploy a Counter (or any contract) against the inner TestVM
480	        let mut contract = Counter::from(vm.inner());
481	
482	        // 3) Before any mocks, count should be zero
483	        assert_eq!(vm.mock_call_count(), 0);
484	
485	        // 4) Define two mock calls
486	        let addr = Address::from([0x05; 20]);
487	        let data = vec![1, 2, 3];
488	        vm.mock_call(addr, data.clone(), Ok(vec![0xAA]));
489	        vm.mock_call(addr, data, Err(vec![0xBB]));
490	
491	        // 5) Now our helper sees exactly two mocks
492	        assert_eq!(vm.mock_call_count(), 2);
493	
494	        // 6) And of course external calls still work through inner:
495	        let _ = contract.call_external_contract(addr, vec![1, 2, 3]);
496	        let _ = contract.call_external_contract(addr, vec![1, 2, 3]);
497	
498	        // 7) But the number of *defined* mocks remains the same
499	        assert_eq!(vm.mock_call_count(), 2);
500	    }
501	}
