    w.release_eth().unwrap();

    assert_eq!(w.released_eth(), U256::from(1000));
    assert_eq!(logs_of::<EtherReleased>(&vm), 1);
}

#[test]
fn release_eth_half_vested() {
    let vm = TestVM::default();
    vm.set_block_timestamp(500);
    vm.set_balance(vm.contract_address(), U256::from(1000));
    let mut w = wallet(&vm, 0, 1000);

    vm.mock_call(BOB, vec![], U256::from(500), Ok(vec![]));
    w.release_eth().unwrap();
    assert_eq!(w.released_eth(), U256::from(500));
    assert_eq!(w.releasable_eth(), U256::ZERO);
}

#[test]
fn release_eth_reverts_when_transfer_fails() {
    let vm = TestVM::default();
    vm.set_block_timestamp(1_500);
    vm.set_balance(vm.contract_address(), U256::from(1000));
    let mut w = wallet(&vm, 0, 1000);

    vm.mock_call(BOB, vec![], U256::from(1000), Err(b"nope".to_vec()));
    let err = w.release_eth().unwrap_err();
    assert!(
        matches!(err, Error::ReleaseEtherFailed(ReleaseEtherFailed { ref reason }) if reason == "nope"),
        "{err:?}"
    );
}

#[test]
fn vested_amount_eth_counts_balance_and_released() {
    let vm = TestVM::default();
    vm.set_block_timestamp(0);
    vm.set_balance(vm.contract_address(), U256::from(1000));
    let w = wallet(&vm, 0, 1000);
    assert_eq!(w.vested_amount_eth(1_000), U256::from(1000));
    assert_eq!(w.vested_amount_eth(250), U256::from(250));
    // Another account's balance must not be counted.
    vm.set_balance(ALICE, U256::from(1_000_000));
    assert_eq!(w.vested_amount_eth(1_000), U256::from(1000));
}

#[test]
fn vested_amount_erc20_invalid_token() {
    let vm = TestVM::default();
    let mut w = wallet(&vm, 0, 1000);
    let calldata = balanceOfCall { account: vm.contract_address() }.abi_encode();
    vm.mock_static_call(TOKEN, calldata, Err(vec![]));
    let err = w.vested_amount_erc20(TOKEN, 10).unwrap_err();
    assert!(matches!(err, Error::InvalidToken(InvalidToken { token }) if token == TOKEN), "{err:?}");
}

#[test]
fn releasable_and_release_erc20() {
    let vm = TestVM::default();
    vm.set_block_timestamp(2_000);
    vm.set_code(TOKEN, vec![0xfe]);
    let mut w = wallet(&vm, 0, 1000);

    // Both mocked responses are the 32-byte word `1` (TestVM returns the last
    // registered return data for every call).
    let one = U256::from(1);
    let balance_calldata = balanceOfCall { account: vm.contract_address() }.abi_encode();
    let transfer_calldata = transferCall { to: BOB, value: one }.abi_encode();
    vm.mock_static_call(TOKEN, balance_calldata, Ok(balanceOfCall::abi_encode_returns(&one)));
    vm.mock_call(TOKEN, transfer_calldata, U256::ZERO, Ok(transferCall::abi_encode_returns(&true)));

    assert_eq!(w.releasable_erc20(TOKEN).unwrap(), one);
    w.release_erc20(TOKEN).unwrap();
    assert_eq!(w.released_erc20(TOKEN), one);
    assert_eq!(logs_of::<ERC20Released>(&vm), 1);
}

#[test]
fn ownership_through_wallet() {
    let vm = TestVM::default();
    let mut w = wallet(&vm, 0, 1000);
    vm.set_sender(ALICE);
    let err = w.transfer_ownership(ALICE).unwrap_err();
    assert!(matches!(err, Error::UnauthorizedAccount(ownable::OwnableUnauthorizedAccount { account }) if account == ALICE));
    vm.set_sender(BOB);
    w.transfer_ownership(ALICE).unwrap();
    assert_eq!(w.owner(), ALICE);
}

